class TranscribeBase(Base):
    def __init__(self, name: str, options: List[BaseOptions] = []):
        self.name: str = name
        self.optionsList = options
        self.logger: logging.Logger = logging.getLogger(self.__class__.__name__)

    def t_opts(self) -> TranscribeOptions:
        if not getattr(self, '_transcribe_options', None):
            self._transcribe_options = self.get_options(TranscribeOptions)
        return self._transcribe_options

    def supported_models(self) -> List[ModelSpec]:
        try:
            return super().supported_models()
        except AttributeError:
            return []

    def mixins(self):
        return [cls for cls in type(self).mro() if not issubclass(cls, TranscribeBase)]

    def _run(self, method: str):
        results = []
        for cls in self.mixins():
            if method in cls.__dict__:
                result = cls.__dict__[method](self)
                if result is not None:
                    results.extend(result if isinstance(result, list) else [result])
        return results if results else None

    def prepare(self):
        options = self.t_opts()

        if options.device and options.device == K_CPU:
            cpu_threads = options.threads or max(1, (os.cpu_count() or 2) - 1)

            # Must be configured before inference starts.
            torch.set_num_threads(cpu_threads)

        self._run("prepare")
        # self.model = self.load_model()
        # if self.use_diarization():
        #     self.diarize_model = self.load_diarize_model()

    def id(self) -> str:
        options = self.t_opts()
        return '-'.join([options.base, options.model, self.name, self.language()])

    def language(self) -> str:
        options = self.t_opts()
        if not options.language:
            return "auto"
        return options.language

    def base_name(self) -> str:
        options = self.t_opts()
        return options.base

    def close(self):
        self._run("close")

    def __del__(self):
        self.close()


