class AlignProcess(PostProcessing):

    @abstractmethod
    def align(self, audio: np.ndarray, transcription: Transcription, ctxt: TranscriptionContext) -> Transcription:
        raise NotImplementedError("must be implemented in the child class")

    def use_align(self):
        a_opts = self.a_opts()
        if a_opts:
            if hasattr(a_opts, "align") and a_opts.align:
                return True
        return False

    def a_opts(self) -> AlignOptions:
        if not getattr(self, '_align_options', None):
            self._align_options = self.get_options(AlignOptions)
        return self._align_options


class DiarizeProcess(PostProcessing):

    @abstractmethod
    def diarize(self, audio: np.ndarray, ctxt: TranscriptionContext) -> Any:
        raise NotImplementedError("must be implemented in the child class")

    def use_diarization(self):
        d_opts = self.d_opts()
        if hasattr(d_opts, "diarize") and d_opts and d_opts.diarize:
            return True
        return False
